#include <stdlib.h>
#include <math.h>
#include <string.h>
/* sparse shortest augmenting path LAP with global optimality check.
   M: n x n row-major. out: col4row. returns 0 ok, <0 failure */
static int solve_sparse(int n, const double *M, const int *start, const int *adj,
    double *u, double *v, int *col4row, int *row4col,
    double *sh, int *path, char *SR, char *SC, int *heap, int *hpos, int *rem_c, int *rem_r){
  for(int i=0;i<n;i++){u[i]=0;col4row[i]=-1;}
  for(int j=0;j<n;j++){v[j]=0;row4col[j]=-1;}
  for(int cur=0;cur<n;cur++){
    /* dijkstra */
    int nrc=0,nrr=0,hs=0; int sink=-1; double minVal=0; int i=cur;
    for(;;){
      SR[i]=1; rem_r[nrr++]=i;
      for(int e=start[i];e<start[i+1];e++){int j=adj[e]; if(SC[j]) continue;
        double r=minVal+M[(size_t)i*n+j]-u[i]-v[j];
        if(hpos[j]==-2){ /* untouched */
          sh[j]=r;path[j]=i; rem_c[nrc++]=j; hpos[j]=hs; heap[hs++]=j;
          int k=hpos[j]; while(k>0){int p=(k-1)/2; if(sh[heap[p]]<=sh[heap[k]])break; int t=heap[p];heap[p]=heap[k];heap[k]=t;hpos[heap[p]]=p;hpos[heap[k]]=k;k=p;}
        } else if(r<sh[j]){ sh[j]=r;path[j]=i;
          int k=hpos[j]; while(k>0){int p=(k-1)/2; if(sh[heap[p]]<=sh[heap[k]])break; int t=heap[p];heap[p]=heap[k];heap[k]=t;hpos[heap[p]]=p;hpos[heap[k]]=k;k=p;}
        }
      }
      if(hs==0){ sink=-1; break;}
      int j=heap[0]; hs--; if(hs>0){heap[0]=heap[hs];hpos[heap[0]]=0;
        int k=0; for(;;){int l=2*k+1,r2=l+1,m=k; if(l<hs&&sh[heap[l]]<sh[heap[m]])m=l; if(r2<hs&&sh[heap[r2]]<sh[heap[m]])m=r2; if(m==k)break; int t=heap[m];heap[m]=heap[k];heap[k]=t;hpos[heap[m]]=m;hpos[heap[k]]=k;k=m;}}
      hpos[j]=-1; SC[j]=1; minVal=sh[j];
      if(row4col[j]<0){sink=j;break;}
      i=row4col[j];
    }
    if(sink<0){ for(int k=0;k<nrc;k++){SC[rem_c[k]]=0;hpos[rem_c[k]]=-2;} for(int k=0;k<nrr;k++)SR[rem_r[k]]=0; return -1;}
    u[cur]+=minVal;
    for(int k=0;k<nrr;k++){int r=rem_r[k]; if(r!=cur) u[r]+=minVal-sh[col4row[r]]; SR[r]=0;}
    for(int k=0;k<nrc;k++){int c=rem_c[k]; if(SC[c]) v[c]-=minVal-sh[c]; SC[c]=0; hpos[c]=-2;}
    int j=sink; for(;;){int r=path[j]; row4col[j]=r; int t=col4row[r]; col4row[r]=j; if(r==cur)break; j=t;}
  }
  return 0;
}

int lap(int n, const double *M, int k, int *col4row){
  char *mask=calloc((size_t)n*n,1);
  int *start=malloc((n+1)*sizeof(int)); int *adj=malloc((size_t)n*n*sizeof(int));
  double *u=malloc(n*8),*v=malloc(n*8),*sh=malloc(n*8);
  int *row4col=malloc(n*4),*path=malloc(n*4),*heap=malloc(n*4),*hpos=malloc(n*4),*rc=malloc(n*4),*rr=malloc(n*4);
  char *SR=calloc(n,1),*SC=calloc(n,1);
  int *idx=malloc((k+1)*4); double *val=malloc((k+1)*8);
  if(k>n)k=n;
  /* k smallest per row */
  for(int i=0;i<n;i++){ const double *row=M+(size_t)i*n; int c=0;
    for(int j=0;j<n;j++){double x=row[j]; if(c<k||x<val[c-1]){int p=(c<k)?c++:c-1; while(p>0&&val[p-1]>x){val[p]=val[p-1];idx[p]=idx[p-1];p--;} val[p]=x;idx[p]=j;}}
    for(int t=0;t<c;t++) mask[(size_t)i*n+idx[t]]=1; }
  /* k smallest per column */
  {double *cv=malloc((size_t)n*(k+1)*8); int *ci=malloc((size_t)n*(k+1)*4); int *cc=calloc(n,4);
   for(int i=0;i<n;i++){const double *row=M+(size_t)i*n; for(int j=0;j<n;j++){double x=row[j]; int c=cc[j]; double *vv=cv+(size_t)j*(k+1); int *ii=ci+(size_t)j*(k+1);
     if(c<k||x<vv[c-1]){int p=(c<k)?c++:c-1; while(p>0&&vv[p-1]>x){vv[p]=vv[p-1];ii[p]=ii[p-1];p--;} vv[p]=x;ii[p]=i; cc[j]=c;}}}
   for(int j=0;j<n;j++) for(int t=0;t<cc[j];t++) mask[(size_t)ci[(size_t)j*(k+1)+t]*n+j]=1;
   free(cv);free(ci);free(cc);}
  for(int j=0;j<n;j++)hpos[j]=-2;
  int ret=-1;
  for(int it=0;it<50;it++){
    int e=0; for(int i=0;i<n;i++){start[i]=e; for(int j=0;j<n;j++) if(mask[(size_t)i*n+j]) adj[e++]=j;} start[n]=e;
    int r=solve_sparse(n,M,start,adj,u,v,col4row,row4col,sh,path,SR,SC,heap,hpos,rc,rr);
    if(r<0){ /* infeasible: double density by adding all */ if(e==n*n)break; memset(mask,1,(size_t)n*n); continue;}
    int viol=0;
    for(int i=0;i<n;i++){const double *row=M+(size_t)i*n; double ui=u[i]; for(int j=0;j<n;j++){ if(row[j]-ui-v[j]< -1e-12 && !mask[(size_t)i*n+j]){mask[(size_t)i*n+j]=1;viol++;}}}
    if(!viol){ret=it;break;}
  }
  free(mask);free(start);free(adj);free(u);free(v);free(sh);free(row4col);free(path);free(heap);free(hpos);free(rc);free(rr);free(SR);free(SC);free(idx);free(val);
  return ret;
}
