{"command": "export TMPDIR=$PWD/tmp; cat > lap.c <<'EOF'
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <stdio.h>

static void up(int k,int*heap,int*hpos,const double*sh){int x=heap[k];double sx=sh[x];
  while(k>0){int p=(k-1)>>1; if(sh[heap[p]]<=sx)break; heap[k]=heap[p];hpos[heap[k]]=k;k=p;} heap[k]=x;hpos[x]=k;}
static void down(int hs,int*heap,int*hpos,const double*sh){int k=0;int x=heap[0];double sx=sh[x];
  for(;;){int l=2*k+1; if(l>=hs)break; int m=l; if(l+1<hs&&sh[heap[l+1]]<sh[heap[l]])m=l+1; if(sh[heap[m]]>=sx)break; heap[k]=heap[m];hpos[heap[k]]=k;k=m;} heap[k]=x;hpos[x]=k;}

typedef struct { int n; const double*M; int*cnt; int*adj; char*mask; } G_t;

static void add_edge(G_t*g,int i,int j){size_t q=(size_t)i*g->n+j; if(g->mask[q])return; g->mask[q]=1; g->adj[(size_t)i*g->n + g->cnt[i]++]=j;}

/* returns -1 if no augmenting path */
static int ssp(G_t*g,double*u,double*v,int*col4row,int*row4col,double*sh,int*path,char*SC,int*heap,int*hpos,int*rc,int*rr){
  int n=g->n; const double*M=g->M;
  for(int cur=0;cur<n;cur++){ if(col4row[cur]>=0) continue;
    int nrc=0,nrr=0,hs=0,sink=-1; double minVal=0; int i=cur;
    for(;;){
      rr[nrr++]=i; const double*row=M+(size_t)i*n; const int*a=g->adj+(size_t)i*n; int c=g->cnt[i]; double base=minVal-u[i];
      for(int e=0;e<c;e++){int j=a[e]; if(SC[j])continue; double r=base+row[j]-v[j];
        if(hpos[j]==-2){sh[j]=r;path[j]=i;rc[nrc++]=j;heap[hs]=j;hpos[j]=hs;hs++;up(hs-1,heap,hpos,sh);}
        else if(r<sh[j]){sh[j]=r;path[j]=i;up(hpos[j],heap,hpos,sh);} }
      if(hs==0)break;
      int j=heap[0]; hs--; if(hs>0){heap[0]=heap[hs];hpos[heap[0]]=0;down(hs,heap,hpos,sh);}
      hpos[j]=-1; SC[j]=1; minVal=sh[j];
      if(row4col[j]<0){sink=j;break;}
      i=row4col[j];
    }
    if(sink<0){for(int k=0;k<nrc;k++){SC[rc[k]]=0;hpos[rc[k]]=-2;} return -1;}
    u[cur]+=minVal;
    for(int k=1;k<nrr;k++){int r=rr[k]; u[r]+=minVal-sh[col4row[r]];}
    for(int k=0;k<nrc;k++){int c=rc[k]; if(SC[c]) v[c]-=minVal-sh[c]; SC[c]=0; hpos[c]=-2;}
    int j=sink; for(;;){int r=path[j]; row4col[j]=r; int t=col4row[r]; col4row[r]=j; if(r==cur)break; j=t;}
  }
  return 0;
}

static void arr(G_t*g,double*v,int*col4row,int*row4col,int*F,int cap){
  int n=g->n; const double*M=g->M;
  for(int pass=0;pass<2;pass++){
    int nf=0; for(int i=0;i<n;i++) if(col4row[i]<0) F[nf++]=i;
    int k=0; long steps=0, lim=(long)n*8;
    while(k<nf && steps<lim){ steps++;
      int i=F[k++]; const double*row=M+(size_t)i*n; const int*a=g->adj+(size_t)i*n; int c=g->cnt[i];
      double u1=INFINITY,u2=INFINITY; int j1=-1,j2=-1;
      for(int e=0;e<c;e++){int j=a[e]; double x=row[j]-v[j]; if(x<u2){ if(x<u1){u2=u1;j2=j1;u1=x;j1=j;} else {u2=x;j2=j;}}}
      if(j1<0)continue;
      int i0=row4col[j1];
      if(u1<u2){ if(j2>=0) v[j1]-=u2-u1; }
      else if(i0>=0 && j2>=0){ j1=j2; i0=row4col[j1]; }
      if(i0>=0){ col4row[i0]=-1;
        if(u1<u2 && j2>=0) F[--k]=i0; else if(nf<cap) F[nf++]=i0; }
      row4col[j1]=i; col4row[i]=j1;
    }
  }
}

static void fix_rows(G_t*g,double*u,const double*v,int*col4row,int*row4col){
