static double qselect(double*a,int n,int k){int l=0,r=n-1; while(l<r){double pv=a[(l+r)/2]; int i=l,j=r; while(i<=j){while(a[i]<pv)i++; while(a[j]>pv)j--; if(i<=j){double t=a[i];a[i]=a[j];a[j]=t;i++;j--;}} if(k<=j)r=j; else if(k>=i)l=i; else break;} return a[k];}

