static long auction_phase(int n,int*col4row,int nf,double eps,long maxbids,double big){
  long bids=0;
  while(nf>0){ if(++bids>maxbids) return -1;
    int i=F[--nf]; const int*a=adj+(size_t)i*n; const double*cs=cst+(size_t)i*n; int c=cnt[i];
    double w1=INFINITY,w2=INFINITY; int j1=-1;
