  for(int i=0;i<n;i++)fixrow(i,col4row);
  if(dbg){int nf=0;for(int i=0;i<n;i++)nf+=col4row[i]<0;DBG("free %d\n",nf);}
  for(int round=0;round<100;round++){
    int r=ssp(n,col4row);
    DBG("ssp r %d pops %ld scans %ld t %.3f\n",r,POPS,SCN,1e3*(now()-T0)); POPS=SCN=0;
    if(r<0){ for(int i=0;i<n;i++){const double*row=M+(size_t)i*n; for(int j=0;j<n;j++) add(i,j,row[j]);} if(overflow) return -2; for(int i=0;i<n;i++)fixrow(i,col4row); continue; }
    int viol=0;
    for(int i=0;i<n;i++){const double*row=M+(size_t)i*n; double t=u_[i]-1e-14; double m=rmin_g(row,v_,n,-1.0);
      if(m<t){ for(int j=0;j<n;j++) if(row[j]-v_[j]<t) viol+=add(i,j,row[j]); if(overflow) return -2; fixrow(i,col4row);} }
    DBG("viol %d t %.3f\n",viol,1e3*(now()-T0));
    if(!viol){
      /* certificate: assignment is a permutation and every assigned edge is tight */
      int okc=1; for(int j=0;j<n;j++) row4col[j]=-1;
      for(int i=0;i<n;i++){int j=col4row[i]; if(j<0||j>=n||row4col[j]>=0){okc=0;break;} row4col[j]=i;
        double rcst=M[(size_t)i*n+j]-u_[i]-v_[j]; if(rcst>1e-9){okc=0;break;}}
